CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text, super_admin boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE access_tokens (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, contact text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT 'Asia/Jakarta', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','archived')), branding jsonb NOT NULL DEFAULT '{}', success jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), name text NOT NULL, owner boolean NOT NULL DEFAULT false, permissions text[] NOT NULL DEFAULT '{}', UNIQUE(company_id,id), UNIQUE(company_id,name));
CREATE TABLE company_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL, active boolean NOT NULL DEFAULT true, FOREIGN KEY(company_id,role_id) REFERENCES roles(company_id,id), UNIQUE(company_id,user_id));
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), title text NOT NULL, slug text NOT NULL, description text NOT NULL DEFAULT '', position text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT 'Asia/Jakarta', opens_at timestamptz, closes_at timestamptz, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed','archived')), form_version integer NOT NULL DEFAULT 1, fields jsonb NOT NULL DEFAULT '[]', success jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id), UNIQUE(company_id,slug), CHECK(closes_at IS NULL OR opens_at IS NULL OR closes_at>opens_at));
CREATE TABLE form_versions (company_id uuid NOT NULL, campaign_id uuid NOT NULL, version integer NOT NULL, fields jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(campaign_id,version), FOREIGN KEY(company_id,campaign_id) REFERENCES campaigns(company_id,id));
CREATE TABLE interview_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, campaign_id uuid NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, capacity integer NOT NULL CHECK(capacity>0), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed','cancelled')), note text NOT NULL DEFAULT '', FOREIGN KEY(company_id,campaign_id) REFERENCES campaigns(company_id,id), UNIQUE(company_id,campaign_id,id), UNIQUE(campaign_id,starts_at,ends_at), CHECK(ends_at>starts_at));
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, campaign_id uuid NOT NULL, slot_id uuid NOT NULL, name text NOT NULL, email text NOT NULL, phone text NOT NULL, status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','attended','absent','cancelled')), code text UNIQUE NOT NULL, token text UNIQUE NOT NULL, idempotency_key uuid NOT NULL, request_hash text NOT NULL, form_version integer NOT NULL, answers jsonb NOT NULL, consent_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(company_id,campaign_id,slot_id) REFERENCES interview_slots(company_id,campaign_id,id), FOREIGN KEY(campaign_id,form_version) REFERENCES form_versions(campaign_id,version), UNIQUE(campaign_id,idempotency_key));
CREATE UNIQUE INDEX bookings_active_email ON bookings(campaign_id,email) WHERE status<>'cancelled';
CREATE INDEX bookings_slot ON bookings(slot_id,status);
CREATE INDEX bookings_company ON bookings(company_id,created_at DESC);
CREATE TABLE uploaded_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), filename text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, company_id uuid REFERENCES companies(id), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_company ON audit_logs(company_id,created_at DESC);
CREATE TABLE platform_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), settings jsonb NOT NULL DEFAULT '{}');
INSERT INTO platform_settings DEFAULT VALUES;
CREATE TABLE rate_limits (key text PRIMARY KEY, hits integer NOT NULL, expires_at timestamptz NOT NULL);
